Please debug the following Typescript code.

### Problem Description
Fix EventEmitter so off removes only the target callback and once auto-removes after execution.

### Buggy Code
```typescript
export class EventEmitter {
  private listeners: Record<string, Function[]> = {};

  on(event: string, fn: Function): void {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event].push(fn);
  }

  off(event: string, fn: Function): void {
    // Bug: Clears all listeners for this event
    this.listeners[event] = [];
  }

  emit(event: string, ...args: any[]): void {
    const list = this.listeners[event] || [];
    list.forEach(fn => fn(...args));
  }
}
```

Identify the bug, provide the corrected implementation, and supply a verified unit test suite.

### Analysis & Root Cause
Filter listener array in off() to retain non-matching functions, and wrap callbacks in once().

### Corrected Implementation
```typescript
export class EventEmitter {
  private listeners: Record<string, Function[]> = {};

  on(event: string, fn: Function): void {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event].push(fn);
  }

  off(event: string, fn: Function): void {
    if (!this.listeners[event]) return;
    this.listeners[event] = this.listeners[event].filter(cb => cb !== fn);
  }

  once(event: string, fn: Function): void {
    const wrapper = (...args: any[]) => {
      this.off(event, wrapper);
      fn(...args);
    };
    this.on(event, wrapper);
  }

  emit(event: string, ...args: any[]): void {
    const list = [...(this.listeners[event] || [])];
    list.forEach(fn => fn(...args));
  }
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert';
import { EventEmitter } from './solution.ts';

describe('EventEmitter', () => {
  it('handles on, off, and once correctly', () => {
    const ee = new EventEmitter();
    let count1 = 0, count2 = 0;
    const fn1 = () => count1++;
    const fn2 = () => count2++;

    ee.on('data', fn1);
    ee.once('data', fn2);

    ee.emit('data');
    assert.strictEqual(count1, 1);
    assert.strictEqual(count2, 1);

    ee.emit('data');
    assert.strictEqual(count1, 2);
    assert.strictEqual(count2, 1); // once was unregistered

    ee.off('data', fn1);
    ee.emit('data');
    assert.strictEqual(count1, 2);
  });
});
```

