Please debug the following Typescript code.

### Problem Description
Fix AsyncMutex so acquired locks are released sequentially to waiting callers.

### Buggy Code
```typescript
export class AsyncMutex {
  private locked = false;
  private queue: (() => void)[] = [];

  async acquire(): Promise<() => void> {
    if (this.locked) {
      await new Promise<void>(resolve => this.queue.push(resolve));
    }
    this.locked = true;
    // Bug: Release function does not pass lock to the next queued caller
    return () => {
      this.locked = false;
    };
  }
}
```

Identify the bug, provide the corrected implementation, and supply a verified unit test suite.

### Analysis & Root Cause
When releasing the mutex, pop the next resolve function from queue and invoke it, preserving lock ownership.

### Corrected Implementation
```typescript
export class AsyncMutex {
  private locked = false;
  private queue: (() => void)[] = [];

  async acquire(): Promise<() => void> {
    if (this.locked) {
      await new Promise<void>(resolve => this.queue.push(resolve));
    }
    this.locked = true;

    return () => {
      if (this.queue.length > 0) {
        const next = this.queue.shift()!;
        next();
      } else {
        this.locked = false;
      }
    };
  }
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert';
import { AsyncMutex } from './solution.ts';

describe('AsyncMutex', () => {
  it('enforces serial execution of critical sections', async () => {
    const mutex = new AsyncMutex();
    const order: number[] = [];

    async function task(id: number, delayMs: number) {
      const release = await mutex.acquire();
      order.push(id);
      await new Promise(r => setTimeout(r, delayMs));
      release();
    }

    await Promise.all([
      task(1, 20),
      task(2, 10),
      task(3, 5),
    ]);

    assert.deepStrictEqual(order, [1, 2, 3]);
  });
});
```

